  }

  // Write out nodes. This has to be done from rank 0 so we need to gather mc2p.
  struct gkyl_array *mc2p_global =
    mkarr(app->use_gpu, app->gk_geom->geo_corn.mc2p->ncomp, app->global_ext.volume);
  gkyl_comm_array_allgather(
